/// execution.", "newString": "/// A per-account cache of storage slots.
///
/// This holds a bounded number of storage slots for a single account, keyed by
/// [`StorageKey`].
#[derive(Debug, Clone)]
pub struct AccountStorageCache {
    /// The cache of storage slots for this account.
    slots: Cache<StorageKey, StorageValue>,
}

impl AccountStorageCache {
    /// Creates a new [`AccountStorageCache`] with the given maximum number of storage slots.
    pub fn new(max_slots: u64) -> Self {
        Self {
            slots: CacheBuilder::new(max_slots)
                .build_with_hasher(DefaultHashBuilder::default()),
        }
    }

    /// Returns the number of storage slots currently cached.
    pub fn len(&self) -> usize {
        self.slots.run_pending_tasks();
        self.slots.entry_count() as usize
    }

    /// Returns `true` if the cache holds no storage slots.
    pub fn is_empty(&self) -> bool {
        self.len() == 0
    }
}

